import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../core/constants/app_constants.dart';import '../../core/widgets/zaylo_widgets.dart';import '../../repositories/providers.dart';
class PricesScreen extends ConsumerWidget{const PricesScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final data=ref.watch(mockRepositoryProvider).groceries();return Scaffold(appBar:AppBar(title:const Text('Grocery Prices')),floatingActionButton:FloatingActionButton.extended(onPressed:()=>showComingSoon(context,'Submit price'),label:const Text('Submit'),icon:const Icon(Icons.add)),body:ListView(padding:const EdgeInsets.all(16),children:[const TextField(decoration:InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search products or stores')),const ZayloCard(child:Text(AppConstants.mockNotice)),for(final p in data) ListTile(title:Text(p.product),subtitle:Text('${p.store} • ${p.city} • updated ${p.updatedAt.hour}:30'),trailing:Column(mainAxisSize:MainAxisSize.min,children:[Text('\$${p.price.toStringAsFixed(2)}'),TrustBadge(p.verified)]),onTap:()=>showComingSoon(context,'Report incorrect price'))]));}}
